<template><div class="app-container" v-loading="loading"><h3>行业模板与页面预设</h3><el-alert title="选择内置行业布局，先看示意和变更清单，再应用为草稿。保留企业资料、Logo、轮播、统计和原导航；不会修改现有内容或自动发布。" :closable="false"/>
 <el-table :data="presets" highlight-current-row @current-change="select"><el-table-column label="选择" width="70"><template #default="s"><el-radio v-model="selected" :value="s.row.id" @change="select(s.row)"><span/></el-radio></template></el-table-column><el-table-column prop="name" label="行业方案" width="180"/><el-table-column prop="description" label="用途"/><el-table-column prop="theme" label="模板" width="120"/><el-table-column label="操作" width="130"><template #default="s"><el-button link type="primary" @click.stop="sample(s.row)">查看布局示意</el-button></template></el-table-column></el-table><pagination v-if="presetTotal" :total="presetTotal" v-model:page="pg.pageNum" v-model:limit="pg.pageSize" @pagination="loadPresets"/>
 <el-form label-width="150px" style="margin-top:18px;max-width:900px" @submit.prevent><el-form-item label="页面地址前缀"><el-input v-model="prefix" maxlength="40" placeholder="如 company（小写字母开头、数字或连字符）"/></el-form-item><el-form-item label="同时生成页面草稿"><el-checkbox-group v-model="keys"><el-checkbox value="about" label="关于我们"/><el-checkbox value="services" label="服务能力"/><el-checkbox value="contact" label="联系我们"/></el-checkbox-group></el-form-item><el-form-item><span>可不选，仅应用外观。选中的页面只新建，遇到地址占用会停止，不覆盖已有页面。</span></el-form-item><el-form-item><el-button type="primary" :disabled="!selected" :loading="busy" @click="preview">预览变更清单</el-button><el-button @click="reloadSite">刷新当前草稿版本</el-button><span v-if="site"> 当前版本 {{site.version}}</span></el-form-item></el-form>
 <template v-if="plan"><el-divider>将应用的变更（当前草稿 → 预设草稿）</el-divider><el-descriptions border :column="2"><el-descriptions-item label="模板">{{site?.config.theme}} → {{plan.config.theme}}</el-descriptions-item><el-descriptions-item label="配色">{{site?.config.palette}} → {{plan.config.palette}}</el-descriptions-item><el-descriptions-item label="首页组件">替换为 {{plan.config.blocks.map(x=>x.title||x.kind).join('、')}}</el-descriptions-item><el-descriptions-item label="导航">保留原导航，追加 {{plan.pages.length}} 个新页面入口</el-descriptions-item><el-descriptions-item label="样式">常规密度 / 标准字号 / 常规宽度 / 柔和圆角 / 网格列表</el-descriptions-item><el-descriptions-item label="栏目布局">清除栏目单独布局，使用本预设的默认网格</el-descriptions-item></el-descriptions><el-alert v-for="w in plan.warnings" :key="w" :title="w" type="info" :closable="false"/><el-alert v-for="w in plan.conflicts" :key="w" :title="w" type="error" :closable="false"/>
 <el-table :data="plan.pages"><el-table-column prop="title" label="新增页面草稿"/><el-table-column prop="slug" label="访问地址"/><el-table-column prop="summary" label="后续要改什么"/></el-table><el-form label-width="100px" style="margin-top:12px;max-width:800px"><el-form-item label="应用原因"><el-input v-model="reason" maxlength="300" placeholder="记录本次应用方案的原因"/></el-form-item><el-form-item><el-button v-hasPermi="['cms:preset:apply']" type="primary" :disabled="plan.conflicts.length>0" :loading="busy" @click="apply">应用为草稿</el-button></el-form-item></el-form></template>
 <el-alert v-if="applied" :title="`已应用 #${applied.applicationId}，外观草稿版本${applied.siteVersionAfter}；新增页面ID：${applied.pageIds.join('、')||'无'}。线上未改变。`" type="success" :closable="false"/><p><el-button @click="router.push('/cms/page')">去编辑 / 发布新页面</el-button><el-button @click="router.push('/cms/site')">去预览 / 发布站点外观</el-button></p>
 <el-divider>应用记录</el-divider><el-table :data="history"><el-table-column prop="applicationId" label="记录" width="80"/><el-table-column prop="presetId" label="方案"/><el-table-column prop="createBy" label="操作人" width="110"/><el-table-column label="草稿版本"><template #default="s">{{s.row.siteVersionBefore}} → {{s.row.siteVersionAfter}}</template></el-table-column><el-table-column label="新页面ID"><template #default="s">{{s.row.pageIds.join('、')||'无'}}</template></el-table-column><el-table-column prop="createTime" label="时间" width="170"/><el-table-column prop="remark" label="原因"/></el-table><pagination v-if="historyTotal" :total="historyTotal" v-model:page="hpg.pageNum" v-model:limit="hpg.pageSize" @pagination="loadHistory"/>
 <el-dialog v-model="sampleOpen" title="内置布局示意 · 不包含你的真实内容" width="min(1250px,calc(100vw - 24px))" append-to-body destroy-on-close><iframe v-if="sampleHtml" :srcdoc="sampleHtml" sandbox="" referrerpolicy="no-referrer" title="行业布局示意" style="width:100%;height:65vh;border:1px solid #eee"/></el-dialog>
</div></template>
<script setup>
import{ref,reactive,watch,onMounted,onBeforeUnmount,onDeactivated,onActivated}from'vue';import{useRouter}from'vue-router';import{ElMessage,ElMessageBox}from'element-plus';import{workflow}from'@/api/cms/workflow'
const router=useRouter(),presets=ref([]),presetTotal=ref(0),selected=ref(''),prefix=ref('company'),keys=ref([]),site=ref(),plan=ref(),reason=ref(''),requestId=ref(''),applied=ref(),history=ref([]),historyTotal=ref(0),busy=ref(false),loading=ref(false),sampleOpen=ref(false),sampleHtml=ref(''),pg=reactive({pageNum:1,pageSize:10}),hpg=reactive({pageNum:1,pageSize:10});let epoch=0,sampleEpoch=0,resume=false
watch([selected,prefix,keys],()=>{plan.value=null;requestId.value=''}, {deep:true})
function select(row){if(row)selected.value=row.id}async function loadPresets(){const n=epoch,r=await workflow('presets/list','get',undefined,{...pg});if(n===epoch){presets.value=r.rows;presetTotal.value=r.total;if(!selected.value&&r.rows.length)selected.value=r.rows[0].id}}async function reloadSite(){const n=epoch,r=await workflow('site');if(n===epoch){site.value=r.data;plan.value=null;requestId.value=''}}async function loadHistory(){const n=epoch,r=await workflow('presets/history','get',undefined,{...hpg});if(n===epoch){history.value=r.rows;historyTotal.value=r.total}}async function load(){loading.value=true;try{await Promise.all([loadPresets(),reloadSite(),loadHistory()])}finally{loading.value=false}}
async function preview(){if(busy.value)return;const n=epoch;busy.value=true;try{await reloadSite();if(n!==epoch)return;const r=await workflow('presets/plan','post',{presetId:selected.value,siteVersion:site.value.version,slugPrefix:prefix.value,pageKeys:[...keys.value]});if(n!==epoch)return;plan.value=r.data;requestId.value=crypto.randomUUID();applied.value=null}finally{busy.value=false}}
async function apply(){if(busy.value||!plan.value)return;if(!reason.value.trim()){ElMessage.warning('请填写应用原因');return};const n=epoch,p=plan.value,id=requestId.value;try{await ElMessageBox.confirm(`将调整外观草稿，并新建${p.pages.length}个页面草稿；线上保持现状。确认？`,'应用行业预设');if(n!==epoch||plan.value!==p)return;busy.value=true;const r=await workflow('presets/apply','post',{presetId:p.presetId,siteVersion:p.siteVersion,slugPrefix:p.slugPrefix,pageKeys:p.pageKeys,planSha256:p.planSha256,requestId:id,reason:reason.value});if(n!==epoch)return;applied.value=r.data;plan.value=null;await reloadSite();await loadHistory();ElMessage.success('已应用为草稿，请继续编辑和发布')}catch{}finally{busy.value=false}}
async function sample(row){const n=++sampleEpoch;sampleHtml.value='';sampleOpen.value=true;const r=await workflow(`presets/${row.id}/preview`);if(n===sampleEpoch)sampleHtml.value=r.data}
function close(){++epoch;++sampleEpoch;plan.value=null;sampleOpen.value=false;sampleHtml.value=''}onMounted(load);onBeforeUnmount(close);onDeactivated(()=>{resume=true;close()});onActivated(()=>{if(resume){resume=false;load()}})
</script>
